mapper.select:
select rcl.recognition_confirm_log_id, rcl.jamo_id, j.jamo_char, j.jamo_name, j.jamo_type,
    rcl.confidence, rcl.reg_date
from recognition_confirm_log rcl
join jamo j on rcl.jamo_id = j.jamo_id
where rcl.member_id = #{memberId}
and j.jamo_type = #{category}
order by rcl.reg_date desc
limit #{start}, #{limit}

select count(*)
from recognition_confirm_log rcl
join jamo j on rcl.jamo_id = j.jamo_id
where rcl.member_id = #{memberId}
and j.jamo_type = #{category}
